const LIVE=["Overview","Board","Capacity","Agents","Orchestration","Usage","Librarian","MCP hub","Context","Sessions"];let lastLive=0,liveFp=null,seenN=new Set();
// at most one live refresh per 1.5 s; a change inside that window, or while a field has focus or a <details> is open,
// waits instead of being dropped, so the page always ends on the latest data
function liveRender(){clearTimeout(liveT);if(!LIVE.includes(tab))return;const wait=lastLive+1500-Date.now();
if(wait>0||document.querySelector("details[open],input:focus,textarea:focus,select:focus")){liveT=setTimeout(liveRender,wait>0?wait:1500);return}
lastLive=Date.now();_liveNext=true;render()}
function stopPoll(){if(window._poll){clearInterval(window._poll);window._poll=0}}
if(window.EventSource){const es=new EventSource("/events");es.onopen=stopPoll;es.onmessage=stopPoll;es.addEventListener("change",e=>{stopPoll();const d=JSON.parse(e.data);if(window.K&&K.noteChange)K.noteChange(d);(d.notifications||[]).forEach(n=>{if(!seenN.has(n.id)){seenN.add(n.id);if(seenN.size>1||Date.now()-boot>3000)toast((n.level==="warn"?"⚠ ":"")+n.title)}});/* the first event (and a reconnect with nothing new) only says where the hub is: the page already shows that */const fresh=liveFp!==null&&d.fp!==liveFp;liveFp=d.fp;if(fresh)liveRender()});es.onerror=()=>{if(!window._poll)window._poll=setInterval(liveRender,5000)}}else{setInterval(liveRender,5000)}
